package com.bank.dsa;

import java.util.logging.*;

// Runnable demo: route a transaction ID to lane A (even) or lane B (odd).
public class EvenOddDemo {
    private static final Logger log = Logger.getLogger(EvenOddDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ParityRouter router = new ParityRouter();

        long txnId = 7;  // Rajesh's transaction on SAV2001
        String lane = router.classify(txnId);
        log.info(() -> "Txn " + txnId + " for SAV2001 is " + lane);
    }
}

// ─── Would be in ParityRouter.java in a real project ───
class ParityRouter {
    // Even -> lane A, Odd -> lane B. Test remainder against 0 (safe for negatives).
    String classify(long id) {
        if (id % 2 == 0) {            // decision: N % 2 == 0 ?
            return "EVEN -> processing lane A";
        } else {
            return "ODD -> processing lane B";
        }
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
